import json,pathlib,itertools
from decimal import Decimal as D, ROUND_HALF_UP, ROUND_HALF_EVEN
L=json.loads(pathlib.Path("tests/reference_totals.json").read_text())
def q(x,r): return float(D(str(x)).quantize(D("0.01"),rounding=r))
def calc(lines,tax,where,how):
    use_dec = how in ("pdu","pde")
    sub = D("0") if use_dec else 0.0
    for qty,p,disc in lines:
        if use_dec:
            net = D(str(qty))*D(str(p))*(D("1")-D(str(disc))/D("100"))
            if where=="perline":
                r = ROUND_HALF_UP if how=="pdu" else ROUND_HALF_EVEN
                net = net.quantize(D("0.01"),rounding=r)
        else:
            net = qty*p*(1-disc/100.0)
            if where=="perline":
                net = round(net,2) if how=="fr" else q(net,ROUND_HALF_UP)
        sub += net
    if use_dec:
        tot = sub*(D("1")+D(str(tax))/D("100"))
        r = ROUND_HALF_UP if how=="pdu" else ROUND_HALF_EVEN
        return float(tot.quantize(D("0.01"),rounding=r))
    else:
        tot = sub*(1+tax/100.0)
        return round(tot,2) if how=="fr" else q(tot,ROUND_HALF_UP)
for where in ["perline","final"]:
    for how in ["fr","fdu","pdu","pde"]:
        n=sum(1 for k,c in L.items() if calc([tuple(x) for x in c["lines"]],c["tax_pct"],where,how)==c["expected_total"])
