import json, pathlib, itertools
from decimal import Decimal, ROUND_HALF_UP, ROUND_HALF_EVEN, ROUND_HALF_DOWN
LED = json.loads(pathlib.Path('tests/reference_totals.json').read_text())

def r_floatround(x): return round(x, 2)
def r_decstr(mode):
    return lambda x: float(Decimal(str(x)).quantize(Decimal('0.01'), mode))
def r_decbin(mode):
    return lambda x: float(Decimal(x).quantize(Decimal('0.01'), mode))

rounders = {
  'float_round': r_floatround,
  'decstr_HU': r_decstr(ROUND_HALF_UP),
  'decstr_HE': r_decstr(ROUND_HALF_EVEN),
  'decstr_HD': r_decstr(ROUND_HALF_DOWN),
  'decbin_HU': r_decbin(ROUND_HALF_UP),
  'decbin_HE': r_decbin(ROUND_HALF_EVEN),
  'decbin_HD': r_decbin(ROUND_HALF_DOWN),
}

def total(name, line_rounder, total_rounder, per_line):
    case = LED[name]
    sub = 0.0
    for q,u,d in case['lines']:
        net = (q*u)*(1 - d/100.0)
        sub += line_rounder(net) if per_line else net
    return total_rounder(sub*(1 + case['tax_pct']/100.0))

# brute force every combination, report which combos match ALL 8 cases
names = sorted(LED)
winners = []
for per_line in (True, False):
    for lr_name, lr in rounders.items():
        for tr_name, tr in rounders.items():
            ok = all(total(n, lr, tr, per_line)==LED[n]['expected_total'] for n in names)
            if ok:
                winners.append((per_line, lr_name, tr_name))
print('WINNERS (per_line, line_rounder, total_rounder):')
for w in winners: print(' ', w)
if not winners:
    print('NO exact combo. Per-case breakdown for float_round per-line:')
    for n in names:
        print(n, 'expected', LED[n]['expected_total'],
              'got', total(n, r_floatround, r_floatround, True))

